<?php /** Recent class test marks; absent students show "Absent" rather than 0. Expects $tests, optional $testsLink. */ ?>
<section class="module-card"><header class="module-card__header"><div><h2>Class Test Marks</h2><p>Latest class tests.</p></div><?php if(!empty($testsLink)):?><a class="btn btn--secondary" href="<?=e($testsLink)?>">View all</a><?php endif?></header><div class="module-card__body"><div class="table-scroll"><table class="data-table mobile-records"><thead><tr><th>Date</th><th>Test</th><th>Subject</th><th>Obtained</th><th>Total</th></tr></thead><tbody>
<?php foreach($tests as $t): $abs=!empty($t['is_absent']); ?><tr><td data-label="Date"><?=e($t['test_date'])?></td><td data-label="Test" class="record-title"><?=e($t['title'])?></td><td data-label="Subject"><?=e($t['subject']??'—')?></td><td data-label="Obtained"><?=$abs?'<span class="status-badge status-badge--absent">Absent</span>':e((string)$t['obtained_marks'])?></td><td data-label="Total"><?=e((string)$t['total_marks'])?></td></tr><?php endforeach?>
<?php if(!$tests):?><tr><td colspan="5"><div class="compact-empty"><h3>No class test marks yet</h3><p>Marks appear here once your teacher enters them.</p></div></td></tr><?php endif?>
</tbody></table></div></div></section>
